#!/usr/bin/env node
// Generates cli-spec.json from docs/CLI.md (the binary's own -h output, regenerated by scripts/gen-cli-docs.sh) and the
// chatHelp constant of cmd/sleipnir/chat.go. Deterministic: same inputs, same bytes.
//
//   node gen-cli-spec.mjs [REPO_ROOT]   (default: the worktree this pack was built from)
//
// Output: cli-spec.json next to this script, and a table of what was found on stdout.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repo = process.argv[2] || '/home/thanos/Documents/Sleipnir/.claude/worktrees/sleipnir-web-interface-cc5a2f';
const md = fs.readFileSync(path.join(repo, 'docs/CLI.md'), 'utf8').split('\n');
const chatGo = fs.readFileSync(path.join(repo, 'cmd/sleipnir/chat.go'), 'utf8');
const chatTty = fs.readFileSync(path.join(repo, 'cmd/sleipnir/chat_tty.go'), 'utf8');

// ---------------------------------------------------------------------------------------------------------------------
// 1. split CLI.md into sections by heading, and find the <!-- flags: NAME --> blocks (the -h listing) in each
// ---------------------------------------------------------------------------------------------------------------------
const sections = []; // {level, title, line, prose[], blocks[{name, text}]}
let cur = null;
for (let i = 0; i < md.length; i++) {
  const h = /^(#{2,4}) (.+)$/.exec(md[i]);
  if (h) {
    cur = { level: h[1].length, title: h[2].trim(), line: i + 1, prose: [], blocks: [] };
    sections.push(cur);
    continue;
  }
  const b = /^<!-- flags: (.+) -->$/.exec(md[i]);
  if (b && cur) {
    const name = b[1].trim();
    let j = i + 1;
    if (!md[j].startsWith('```')) throw new Error('flags block without fence at line ' + (i + 1));
    const body = [];
    for (j++; j < md.length && !md[j].startsWith('```'); j++) body.push(md[j]);
    cur.blocks.push({ name, text: body });
    i = j;
    continue;
  }
  if (cur) cur.prose.push(md[i]);
}

// ---------------------------------------------------------------------------------------------------------------------
// 2. parse one flag listing
// ---------------------------------------------------------------------------------------------------------------------
// Go's flag package prints "  -name type" then "        description"; "value" is a custom flag.Value (here: repeatable),
// no type word is a bool. A backquoted word in the usage string becomes the type word (init's "-model sleipnir models").
function parseFlagLines(lines) {
  const flags = [];
  let f = null;
  for (const ln of lines) {
    let m = /^ {2}--?([A-Za-z][\w-]*)(?: (.+))?$/.exec(ln);
    if (m) {
      f = { name: m[1], typeWord: m[2] || '', desc: '' };
      flags.push(f);
      continue;
    }
    m = /^ {8}(.*)$/.exec(ln);
    if (m && f) {
      f.desc = f.desc ? f.desc + ' ' + m[1] : m[1];
      continue;
    }
  }
  return flags.map(normFlag);
}

function normFlag(f) {
  const tw = f.typeWord;
  let arg = 'bool';
  let repeatable = false;
  if (tw === 'string') arg = 'string';
  else if (tw === 'int') arg = 'int';
  else if (tw === 'uint') arg = 'uint';
  else if (tw === 'float') arg = 'float';
  else if (tw === 'duration') arg = 'duration';
  else if (tw === 'value') { arg = 'string'; repeatable = true; }
  else if (tw) arg = 'string'; // a backquoted placeholder, e.g. "sleipnir models"
  let desc = f.desc;
  let def = null, defaultNote = null;
  const dm = /\s*\(default (.+)\)$/.exec(desc);
  let noteFromDefault = null;
  if (dm) {
    let v = dm[1];
    const quoted = /^"(.*)"$/.exec(v);
    desc = desc.slice(0, dm.index);
    if (arg === 'int' || arg === 'uint' || arg === 'float') {
      // "(default 2; -1 disables)": the number is the default, the remark stays in the description
      const nm = /^(-?\d+(?:\.\d+)?)(?:;\s*(.*))?$/.exec(v);
      if (nm) {
        def = Number(nm[1]);
        if (nm[2]) desc += ' (' + nm[2] + ')';
      } else noteFromDefault = v;
    } else if (arg === 'bool') def = v === 'true';
    else if (quoted) def = quoted[1];
    else if (/^[^\s,]+$/.test(v)) def = v;
    else noteFromDefault = v;
  }
  // "(default: the configured model)" is prose, not a value
  const dn = /\s*\(default: ([^)]*)\)\s*$/.exec(desc) || /\s*\(default: ([^)]*)\)/.exec(desc);
  if (dn) defaultNote = dn[1];
  if (noteFromDefault) defaultNote = noteFromDefault;
  return { name: f.name, arg, default: def, ...(defaultNote ? { defaultNote } : {}), repeatable, desc: desc.trim() };
}

// ---------------------------------------------------------------------------------------------------------------------
// 3. hand-curated facts that CLI.md states in prose (not in a listing): positionals and enumerations. Each carries the
//    sentence it comes from so a reader can check it. Everything else is parsed.
// ---------------------------------------------------------------------------------------------------------------------
const POSITIONAL = {
  'init': [],
  'config': [],
  'sessions': [],
  'sessions prune': [],
  'chat': [],
  'run': [{ name: 'PROMPT', required: false, desc: 'the goal: the remaining words, or - to read stdin', variadic: true }],
  'swarm': [
    { name: 'N', required: true, desc: 'number of workers (1 or more; the manager comes on top)' },
    { name: 'GOAL', required: false, desc: 'the goal: the remaining words, or - to read stdin', variadic: true },
  ],
  'recon': [{ name: 'DIR', required: false, desc: 'project directory (default: the current one)' }],
  'inspect': [{ name: 'SESSION|DIR', required: false, desc: 'a session id (or the start of one), or a session directory; default: the newest session' }],
  'watch': [{ name: 'SESSION', required: false, desc: 'a session id (or the start of one), a session directory, an events.jsonl, or latest' }],
  'replay': [{ name: 'SESSION', required: false, desc: 'a session id (or the start of one), a session directory, an events.jsonl, or latest' }],
  'doctor': [],
  'models': [{ name: 'WORDS', required: false, desc: 'each word narrows the search (all must appear, any case)', variadic: true }],
  'update': [],
  'login': [{ name: 'PROVIDER', required: false, desc: 'heimdall, openrouter, openai, anthropic, chatgpt, ...' }],
  'logout': [{ name: 'PROVIDER', required: true, desc: 'the provider whose key (or ChatGPT sign-in) to remove' }],
  'schedule': [],
  'schedule add': [{ name: 'GOAL', required: true, desc: 'the goal the scheduled run works on', variadic: true }],
  'schedule rm': [{ name: 'ID', required: true, desc: 'the job id `sleipnir schedule` lists' }],
  'daemon': [],
  'demo': [],
  'mock': [],
  'sim': [],
  'friction': [{ name: 'PATH', required: true, desc: 'a session directory, a directory of sessions, or a benchmark run directory', variadic: true }],
  'version': [],
  'mcp list': [],
  'mcp approve': [{ name: 'NAME', required: true, desc: 'the project server to approve' }],
  'mcp revoke': [{ name: 'NAME', required: true, desc: 'the approval to forget' }],
  'mcp test': [{ name: 'NAME', required: false, desc: 'servers to start (default: all)', variadic: true }],
  'trust': [],
  'trust add': [],
  'trust forget': [],
  'trust list': [],
  'models fav list': [],
  'models fav add': [{ name: 'REF', required: true, desc: 'provider/model', variadic: true }],
  'models fav rm': [{ name: 'REF', required: true, desc: 'provider/model', variadic: true }],
  'rl taskgen git': [], 'rl taskgen mutate': [], 'rl taskgen recall': [], 'rl taskgen fixture': [], 'rl rollout': [], 'rl eval': [], 'rl serve': [],
  'rl taskgen composite': [{ name: 'TASKS', required: true, desc: 'the tasks file to combine' }],
  'rl tasks validate': [{ name: 'FILE', required: true, desc: 'tasks file (JSON lines)' }],
  'rl tasks stats': [{ name: 'FILE', required: true, desc: 'tasks file (JSON lines)' }],
  'rl tasks filter': [{ name: 'FILE', required: true, desc: 'tasks file (JSON lines)' }],
  'rl tasks split': [{ name: 'FILE', required: true, desc: 'tasks file (JSON lines)' }],
  'rl tasks check': [{ name: 'FILE', required: true, desc: 'tasks file (JSON lines)' }],
  'rl reward': [{ name: 'RUN_DIR', required: true, desc: 'run directories to re-score', variadic: true }],
  'rl report': [{ name: 'RUN_DIR|REPORT.json', required: true, desc: 'run directories or saved reports', variadic: true }],
  'rl compare': [{ name: 'A', required: true, desc: 'a run directory or a saved report' }, { name: 'B', required: true, desc: 'a run directory or a saved report' }],
  'rl export': [{ name: 'RUN_DIR', required: true, desc: 'run directories to export', variadic: true }],
  'rl expand': [{ name: 'EXPORT.jsonl', required: true, desc: 'a canonical export' }],
  'rl verify': [{ name: 'RUN_DIR', required: true, desc: 'run directories whose recorded prompts to replay', variadic: true }],
  'rl show': [
    { name: 'RUN_DIR', required: true, desc: 'a run directory' },
    { name: 'TASK/SAMPLE', required: false, desc: 'one episode of it' },
  ],
};
const CHOICES = {
  mode: ['default', 'accept-edits', 'plan', 'bypass', 'yolo'],
  'perm-mode': ['accept-edits', 'default', 'plan', 'bypass', 'yolo'],
  isolation: ['none', 'worktree'],
  view: ['cockpit', 'cache', 'mail', 'board'],
  scenario: ['handbook', 'shop'],
  provider: ['heimdall', 'openrouter', 'openai', 'custom'],
  'verify-policy': ['all', 'any', 'majority'],
  advantage: ['grpo', 'rloo', 'broadcast', 'anchor', 'none'],
  'group-by': ['task', 'task+policy', 'group'],
  reasoning: ['drop', 'field', 'keep'],
  'workspace-mode': ['export', 'clone'],
  mode_sim: ['compare', 'scenarios', 'pins', 'agents'],
  provider_sim: ['anthropic', 'marketplace'],
  format_export: ['steps', 'tokens', 'groups', 'sft', 'dpo', 'kto', 'atif', 'canonical'],
  format_report: ['table', 'md', 'json'],
  format_compare: ['table', 'json'],
  category: ['permission', 'tool', 'agent', 'request', 'cache', 'compaction', 'file', 'call'],
};
function choicesFor(cmdPath, flag) {
  const p = cmdPath.join(' ');
  if (flag.name === 'mode') {
    if (p === 'sim') return CHOICES.mode_sim;
    if (p === 'rl rollout' || p === 'rl eval') return null; // single | swarm:N | empty
    return CHOICES.mode;
  }
  if (flag.name === 'provider') return p === 'sim' ? CHOICES.provider_sim : CHOICES.provider;
  if (flag.name === 'format') return p === 'rl export' ? CHOICES.format_export : p === 'rl report' ? CHOICES.format_report : p === 'rl compare' ? CHOICES.format_compare : null;
  if (flag.name === 'category') return CHOICES.category;
  if (CHOICES[flag.name]) return CHOICES[flag.name];
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// 4. build the command list
// ---------------------------------------------------------------------------------------------------------------------
const commands = [];
const seen = new Set();
function add(cmd) {
  const key = cmd.path.join(' ');
  if (seen.has(key)) throw new Error('duplicate command ' + key);
  seen.add(key);
  commands.push(cmd);
}

function firstSentence(proseLines) {
  const text = proseLines.join(' ').replace(/\s+/g, ' ').trim();
  // skip a leading list / table marker
  const m = /^(.+?[.!?])(?:\s|$)/.exec(text);
  let s = (m ? m[1] : text).replace(/`/g, '').replace(/\*\*/g, '');
  if (s.length > 220) s = s.slice(0, 217).replace(/\s+\S*$/, '') + '...';
  return s;
}
function proseOf(sec) {
  // prose before the first block, without blank-only noise and fenced examples
  const out = [];
  let fence = false;
  for (const l of sec.prose) {
    if (l.startsWith('```')) { fence = !fence; continue; }
    if (fence) continue;
    if (l.startsWith('<!--') || !l.trim()) { if (out.length) break; else continue; }
    if (l.startsWith('|') || l.startsWith('* ') || l.startsWith('- ')) { if (out.length) break; else continue; }
    out.push(l.trim());
  }
  return out;
}
function usageLine(blockText) {
  for (const l of blockText) {
    const m = /^usage: (.+)$/i.exec(l.trim());
    if (m) return m[1].trim();
  }
  return null;
}
// flags the usage line says are required: "--repo PATH" outside brackets
function requiredFromUsage(u) {
  if (!u) return [];
  const noBr = u.replace(/\[[^\]]*\]/g, ' ');
  const out = [];
  const re = /--?([a-z][\w-]*)\s+(?:[A-Za-z_.<][^\s]*)/g;
  let m;
  while ((m = re.exec(noBr))) out.push(m[1]);
  return out;
}

function finish(path_, usage, summary, flagsParsed, sec, extra = {}) {
  const key = path_.join(' ');
  const req = new Set(requiredFromUsage(usage));
  const flags = flagsParsed.map((f) => {
    const o = { ...f };
    const ch = choicesFor(path_, f);
    if (ch) o.choices = ch;
    if (req.has(f.name) && f.default === null && !f.defaultNote && !/\(default/.test(f.desc)) o.required = true;
    return o;
  });
  if (!(key in POSITIONAL)) throw new Error('no positional entry for ' + key);
  add({
    path: path_,
    usage: usage ? (usage.startsWith('sleipnir') ? usage : 'sleipnir ' + usage) : 'sleipnir ' + key + (flags.length ? ' [flags]' : ''),
    summary,
    positional: POSITIONAL[key],
    flags,
    source: sec ? `docs/CLI.md:${sec.line}` : 'docs/CLI.md (prose)',
    ...extra,
  });
}

const byTitle = (t) => sections.find((s) => s.title === t);
const cmdSections = sections.filter((s) => /^`sleipnir [a-z]/.test(s.title));

for (const sec of cmdSections) {
  const cmd = sec.title.replace(/`/g, '').replace(/^sleipnir /, '');
  const parts = cmd.split(' ');
  const prose = firstSentence(proseOf(sec));
  if (parts[0] === 'rl' && parts.length === 1) continue; // the family heading: an index, no flags
  if (cmd === 'sessions') {
    const b = sec.blocks[0];
    finish(['sessions'], 'sleipnir sessions [flags]', 'Lists recorded sessions newest first: id, model, cost, first prompt; an arrow marks one that --resume can continue.', parseFlagLines(b.text), sec);
    continue;
  }
  if (cmd === 'sessions prune') {
    const b = sec.blocks[0];
    const u = usageLine(b.text);
    finish(['sessions', 'prune'], u, 'Deletes recorded sessions that are old (default: older than 30 days, except the newest 20); without --yes it lists what would go.', parseFlagLines(b.text), sec);
    continue;
  }
  if (cmd === 'mcp') {
    const b = sec.blocks[0];
    const sub = [
      ['list', 'sleipnir mcp list [--trust-project]', 'The servers a session here would consider, where each came from and whether it may start.', [{ name: 'trust-project', arg: 'bool', default: null, repeatable: false, desc: 'read the project\'s .sleipnir/config.json and .mcp.json entries (each still needs your approval)' }]],
      ['approve', 'sleipnir mcp approve NAME [--yes]', 'Remember a project entry for this project (shows what it would run and asks first).', [{ name: 'yes', arg: 'bool', default: null, repeatable: false, desc: 'do not ask: you have read what it would run' }]],
      ['revoke', 'sleipnir mcp revoke NAME', 'Forget an approval.', []],
      ['test', 'sleipnir mcp test [NAME...] [--trust-project]', 'Start the servers and list the tools they offer (project entries still need approval).', [{ name: 'trust-project', arg: 'bool', default: null, repeatable: false, desc: 'read the project\'s .sleipnir/config.json and .mcp.json entries (each still needs your approval)' }]],
    ];
    // verify each against the listing so the generator fails if the CLI changes
    for (const [name] of sub) if (!b.text.some((l) => l.trim().startsWith(name + ' '))) throw new Error('mcp ' + name + ' missing from the listing');
    for (const [name, u, s, fl] of sub) finish(['mcp', name], u, s, fl, sec, { parent: 'mcp' });
    continue;
  }
  if (cmd === 'trust') {
    const b = sec.blocks[0];
    const flags = [];
    let inFlags = false;
    for (const l of b.text) {
      if (l.trim() === 'flags:') { inFlags = true; continue; }
      if (!inFlags) continue;
      const m = /^ {2}--([a-z]+)(?: ([A-Z]+))?\s{2,}(.+)$/.exec(l);
      if (m) flags.push({ name: m[1], arg: m[2] ? 'string' : 'bool', default: null, repeatable: false, desc: m[3].trim() });
    }
    const cwd = flags.find((f) => f.name === 'cwd'), yes = flags.find((f) => f.name === 'yes'), all = flags.find((f) => f.name === 'all');
    if (!cwd || !yes || !all) throw new Error('trust flags not found');
    cwd.defaultNote = 'the current one'; cwd.desc = cwd.desc.replace(/ \(default: the current one\)$/, '');
    finish(['trust'], 'sleipnir trust [--cwd DIR]', 'Shows what in this directory\'s project trust would unlock, and whether you said yes to exactly that.', [cwd], sec, { parent: 'trust' });
    finish(['trust', 'add'], 'sleipnir trust add [--yes] [--cwd DIR]', 'Say yes to those files as they are now (shows them and asks first).', [cwd, yes], sec, { parent: 'trust' });
    finish(['trust', 'forget'], 'sleipnir trust forget [--all] [--cwd DIR]', 'Forget the answer for this directory, or for every project.', [cwd, all], sec, { parent: 'trust' });
    finish(['trust', 'list'], 'sleipnir trust list', 'The directories you said yes to, and whether the files in each still are the ones you saw.', [], sec, { parent: 'trust' });
    continue;
  }
  if (cmd === 'run') {
    const b = sec.blocks[0];
    const u = usageLine(b.text);
    const fl = parseFlagLines(b.text);
    finish(['run'], u, 'Runs one goal and exits: the remaining words, or what is piped in, or both.', fl, sec);
    // swarm is documented inside the run section: "sleipnir swarm N "goal" [flags]" is run --swarm N
    const swarmFl = fl.filter((f) => f.name !== 'swarm').map((f) => ({ ...f }));
    finish(['swarm'], 'sleipnir swarm N "goal" [flags]', 'Shorthand for run --swarm: a manager and up to N workers. N counts workers and must be 1 or more.', swarmFl, sec, { aliasOf: 'run --swarm N' });
    continue;
  }
  if (cmd === 'models') {
    const b = sec.blocks[0];
    const fl = parseFlagLines(b.text);
    finish(['models'], 'sleipnir models [words...] [flags]', 'Prints the catalogue of an OpenAI-style marketplace with context size and prices per million tokens; favourites come first, marked *.', fl, sec);
    finish(['models', 'fav', 'list'], 'sleipnir models fav list', 'Lists the favourite models kept as models.favorites in your user configuration.', [], sec, { parent: 'models' });
    finish(['models', 'fav', 'add'], 'sleipnir models fav add provider/model...', 'Star one or more models.', [], sec, { parent: 'models' });
    finish(['models', 'fav', 'rm'], 'sleipnir models fav rm provider/model...', 'Unstar one or more models.', [], sec, { parent: 'models' });
    continue;
  }
  if (cmd === 'login') {
    const b = sec.blocks[0];
    finish(['login'], usageLine(b.text), 'Asks which provider you have a key for and for the key, which it does not echo, and keeps it in ~/.sleipnir/auth.json (mode 0600).', [], sec);
    finish(['logout'], 'sleipnir logout <provider>', 'Removes a stored key, or revokes the ChatGPT sign-in.', [], sec, { parent: 'login' });
    continue;
  }
  if (cmd === 'schedule') {
    const b = sec.blocks[0];
    const fl = parseFlagLines(b.text);
    finish(['schedule'], 'sleipnir schedule [list]', 'Lists the scheduled goals with the next and the last run.', [], sec);
    finish(['schedule', 'add'], 'sleipnir schedule add --cron EXPR [flags] <goal>', 'Adds a goal to run on a schedule; a run is a headless sleipnir run in --cwd with the job\'s model, mode and budget (US$1 by default).', fl, sec, { parent: 'schedule' });
    finish(['schedule', 'rm'], 'sleipnir schedule rm <id>', 'Removes a scheduled goal.', [], sec, { parent: 'schedule' });
    // `cron` is required by the usage line
    const a = commands.find((c) => c.path.join(' ') === 'schedule add');
    a.flags.find((f) => f.name === 'cron').required = true;
    continue;
  }
  if (cmd === 'rl taskgen git' || cmd === 'rl taskgen mutate' || cmd === 'rl taskgen composite' || cmd === 'rl taskgen recall' || cmd === 'rl taskgen fixture' || cmd === 'rl rollout' || cmd === 'rl eval' || cmd === 'rl serve' || cmd === 'rl reward' || cmd === 'rl report' || cmd === 'rl compare' || cmd === 'rl export' || cmd === 'rl expand' || cmd === 'rl verify' || cmd === 'rl show') {
    const b = sec.blocks[0];
    const u = usageLine(b.text);
    let summary = prose;
    if (!summary) summary = { 'rl eval': 'Runs held-out tasks and reports pass@k, cost and protocol quality.', 'rl serve': 'HTTP rollout server for a trainer.', 'rl export': 'Writes trainer-ready data from run directories.', 'rl expand': 'Turns a deduplicated canonical export back into inline form.', 'rl verify': 'Replays every recorded prompt and checks it against its wire hash.', 'rl show': 'Summarises a run directory, or one episode of it.', 'rl reward': 'Re-scores a run directory with different reward weights.' }[cmd];
    finish(parts, u, summary, parseFlagLines(b.text), sec);
    continue;
  }
  if (cmd === 'rl tasks') {
    const fam = firstSentence(proseOf(sec));
    const summaries = {
      validate: 'Checks every task in FILE and reports all problems.',
      stats: 'Counts tasks by kind, tag, language and repository.',
      filter: 'Writes the tasks that match tags, ids or a deterministic sample.',
      split: 'Assigns whole repositories to named splits.',
      check: 'Proves each task sound: the verifier fails on the start and passes with the reference solution.',
    };
    for (const b of sec.blocks) {
      const sub = b.name.replace(/^rl tasks /, '');
      finish(['rl', 'tasks', sub], usageLine(b.text), summaries[sub], parseFlagLines(b.text), sec, { parent: 'rl tasks' });
    }
    continue;
  }
  // everything else: one block, "Usage of X:" or "usage: ..."
  if (sec.blocks.length !== 1) throw new Error(`section ${cmd}: expected one flags block, found ${sec.blocks.length}`);
  const b = sec.blocks[0];
  const u = usageLine(b.text);
  const summaries = {
    init: 'Writes a starter .sleipnir/config.json and AGENTS.md (or, with --user, your ~/.sleipnir/config.json); never overwrites.',
    config: 'Shows the effective configuration and where each value came from; --json prints the merged configuration.',
    chat: 'Interactive session. On a terminal, a manager and eight workers; --swarm N sets the number of workers, --swarm 0 is a single agent.',
    update: 'Installs the latest release over the program that is running; --check only says whether a newer release is out.',
    daemon: 'Starts the scheduled goals that are due, one at a time, looking every half minute; --once starts what is due now and exits.',
    mock: 'Serves the built-in deterministic mock provider (OpenAI-style chat completions with an automatic prefix cache).',
  };
  finish(parts, u || `sleipnir ${cmd} [flags]`, summaries[cmd] || prose, parseFlagLines(b.text), sec);
}

// the family index of `rl`
add({ path: ['rl'], usage: 'sleipnir rl <command> [flags]', summary: 'The RL environment: generate tasks, roll a policy out on them, score, export.', positional: [], flags: [], source: `docs/CLI.md:${byTitle('`sleipnir rl`').line}`, index: true });
add({ path: ['mcp'], usage: 'sleipnir mcp <command> [flags]', summary: 'Tool servers (the Model Context Protocol): list, approve, revoke, test, without starting a session.', positional: [], flags: [], source: `docs/CLI.md:${byTitle('`sleipnir mcp`').line}`, index: true });
add({ path: ['rl', 'taskgen'], usage: 'sleipnir rl taskgen <generator>', summary: 'Make tasks from history (git), authored fixtures (fixture), mutations (mutate) or recall questions (recall), or compose swarm tasks (composite).', positional: [], flags: [], source: 'docs/CLI.md (rl command list)', index: true });
add({ path: ['rl', 'tasks'], usage: 'sleipnir rl tasks <command> FILE', summary: 'Validate, filter, split and check task files.', positional: [], flags: [], source: 'docs/CLI.md (rl command list)', index: true });
add({ path: ['version'], usage: 'sleipnir version', summary: 'Prints sleipnir <version> (<commit>); also --version and -v.', positional: [], flags: [], source: 'docs/CLI.md (commands table)' });
// the top-level `help`
add({ path: ['help'], usage: 'sleipnir help', summary: 'Prints the command list (also --help); every command takes -h.', positional: [], flags: [], source: 'cmd/sleipnir/main.go' });

commands.sort((a, b) => a.path.join(' ').localeCompare(b.path.join(' ')));

// ---------------------------------------------------------------------------------------------------------------------
// 5. the slash commands: chatHelp (the /help text, grouped) joined with chatCommands (arguments and one-line descriptions)
// ---------------------------------------------------------------------------------------------------------------------
const hm = /const chatHelp = `([^`]+)`/.exec(chatGo);
if (!hm) throw new Error('chatHelp not found');
const chatSlash = [];
let group = '';
for (const l of hm[1].split('\n')) {
  if (!l.trim()) continue;
  if (!l.startsWith('/')) { group = l.trim(); continue; }
  // chatHelp is a fixed two-column text: the command and its arguments in the first 19 columns, the description after
  const left = l.slice(0, 19).trim().split(/\s+/);
  const cmd = left[0];
  const args = left.slice(1).join(' ');
  const desc = l.slice(19).trim();
  const nm = cmd.slice(1);
  const ccm = new RegExp(`\\{"${nm}", "([^"]*)", "((?:[^"\\\\]|\\\\.)*)"\\}`).exec(chatTty);
  chatSlash.push({ cmd, args, desc, group, paletteArgs: ccm ? ccm[1] : args, paletteDesc: ccm ? ccm[2].replace(/\\"/g, '"') : desc });
}
// sanity: chatCommands (the palette) and chatHelp must name the same commands except the aliases chatHelp lists in prose
const helpNames = new Set(chatSlash.map((c) => c.cmd.slice(1)));
const palNames = [...chatTty.matchAll(/\{"([a-z]+)", "[^"]*", "/g)].map((m) => m[1]);
const missing = palNames.filter((n) => !helpNames.has(n));
if (missing.length) throw new Error('commands in chatCommands but not in chatHelp: ' + missing.join(','));

const spec = {
  generatedFrom: 'docs/CLI.md',
  generator: 'gen-cli-spec.mjs',
  note: 'flags parsed from the binary\'s own -h output as recorded in docs/CLI.md; positionals, enumerations and subcommand summaries of mcp/trust/models fav/schedule/logout are curated in the generator and each carries its source',
  exitCodes: [
    { code: 0, meaning: 'success; also -h/--help, version, and a chat the person ends' },
    { code: 1, meaning: 'the command failed: any error is printed as `sleipnir: <error>` on stderr' },
    { code: 2, meaning: 'usage: no command, an unknown command, or an unknown or malformed flag' },
    { code: 3, meaning: 'unfinished: a swarm\'s manager stopped with work left undone' },
    { code: 130, meaning: 'interrupted by Ctrl-C (143 for SIGTERM)' },
    { code: 75, meaning: 'try again later (EX_TEMPFAIL): rl rollout or rl eval in which no rollout completed' },
  ],
  commands,
  chatSlash,
};
// compact but readable: one command per block, one flag per line
const J = JSON.stringify;
const cmdText = (c) => '{' + Object.keys(c).filter((k) => k !== 'flags').map((k) => J(k) + ':' + J(c[k])).join(',') + ',"flags":[' + (c.flags.length ? '\n  ' + c.flags.map(J).join(',\n  ') + '\n ' : '') + ']}';
const text = '{\n"generatedFrom":' + J(spec.generatedFrom) + ',\n"generator":' + J(spec.generator) + ',\n"note":' + J(spec.note) + ',\n"exitCodes":' + J(spec.exitCodes) + ',\n"commands":[\n' + spec.commands.map(cmdText).join(',\n') + '\n],\n"chatSlash":[\n' + spec.chatSlash.map(J).join(',\n') + '\n]\n}\n';
JSON.parse(text);
fs.writeFileSync(path.join(here, 'cli-spec.json'), text);

// ---------------------------------------------------------------------------------------------------------------------
// 6. report: what was found, checked against the headings of CLI.md
// ---------------------------------------------------------------------------------------------------------------------
const rows = commands.map((c) => [c.path.join(' '), String(c.flags.length), String(c.flags.filter((f) => f.required).length), String(c.positional.length)]);
const w = Math.max(...rows.map((r) => r[0].length));
console.log('command'.padEnd(w) + '  flags  req  pos');
for (const r of rows) console.log(r[0].padEnd(w) + '  ' + r[1].padStart(5) + '  ' + r[2].padStart(3) + '  ' + r[3].padStart(3));
const headings = md.filter((l) => /^### `sleipnir /.test(l)).map((l) => l.replace(/^### `sleipnir /, '').replace(/`$/, ''));
const blocksN = sections.reduce((n, s) => n + s.blocks.length, 0);
console.log(`\n${commands.length} command paths; ${headings.length} headings "### sleipnir ..." in docs/CLI.md; ${blocksN} <!-- flags --> blocks; ${chatSlash.length} slash commands`);
// every heading must be represented
const have = new Set(commands.map((c) => c.path.join(' ')));
for (const h of headings) if (!have.has(h)) { console.error('HEADING NOT IN SPEC: ' + h); process.exitCode = 1; }
// every flags block must have produced a command
const blockNames = [];
for (const s of sections) for (const b of s.blocks) blockNames.push(b.name);
for (const n of blockNames) if (!have.has(n) && !(n === 'login') && !have.has(n.split(' ')[0])) { console.error('BLOCK NOT IN SPEC: ' + n); process.exitCode = 1; }
// every flag has a type and a description
for (const c of commands) for (const f of c.flags) {
  if (!f.arg || !f.desc) { console.error(`flag ${c.path.join(' ')} --${f.name} lacks type or description`); process.exitCode = 1; }
}
